mapper.codeEditorJavascript:
// Kopf-Validator. Liest nur ab und prueft auf Widerspruch.
//
// GEAENDERT ggue. v1: Eine fehlende Kunden-Nr. ist KEIN Fehler mehr. Es gibt
// Belege ohne gedrucktes Kunden-Nr.-Feld (Kiosk die Ecke, 16.06.2026); die
// Store-Auflösung faellt dann auf den Kommissionär-Namen zurueck (Modul 37).
// Der Dedup-Schluessel entsteht deshalb auch nicht mehr hier, sondern erst,
// wenn die Store-Nummer feststeht.
//
// Blockend bleibt allein das Datum: ohne Leistungsdatum gibt es weder einen
// Dedup-Schluessel noch eine Versionsauswahl.
const errors = [];
const hints = [];

let d = null;
try { d = typeof input.extrakt === 'string' ? JSON.parse(input.extrakt) : input.extrakt; }
catch (e) { errors.push('Antwort ist kein gültiges JSON: ' + e.message); }

const empty = () => ({ ok: false, date: null, customer_no: '', commission_agent: '',
  checked_by: '', signed: false,
  signature_consignor: 'unclear', signature_commission_agent: 'unclear',
  noteText: '', errorText: errors.join(' \u00b7 ') });

if (!d || typeof d !== 'object') {
  if (!errors.length) errors.push('Leere Antwort des Kopf-Lesemoduls');
  return empty();
}

// Kunden-Nr: gedruckt, reine Ziffernfolge. Primaerer Store-Schluessel, aber
// nicht mehr der einzige.
const customer_no = String(d.customer_no == null ? '' : d.customer_no).replace(/\D/g, '');
// Kunden-Nr. nicht lesbar wird hier NICHT mehr vermerkt: Modul 37 dokumentiert
// das Ergebnis der Namens-Rueckfallebene vollstaendig (kein Doppel-Hinweis).


// Belegdatum: kommt aus Belege.Datum (Modul 101), NICHT mehr aus dem Dokument.
// Der Dispatcher liest es gedruckt, prueft es normalisiert gegen und legt es
// dort ab -- die Kreuzprobe sitzt jetzt dort (Regressionsfall: 05.06.2026 darf
// nicht als 06.05.2026 landen). Hier wird nur noch hart auf YYYY-MM-DD gezogen:
// ein ISO-Wert mit Zeitzone wuerde von Airtable als UTC gelesen und als Vortag
// gespeichert. Ohne Datum gibt es weder Dedup-Schluessel noch Versionsauswahl --
// deshalb bleibt es der einzige blockende Kopfwert.
let date = null;
const dateRaw = String(input.date == null ? '' : input.date).trim();
if (dateRaw) {
  const t = dateRaw.split('T')[0].match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (t) date = t[1] + '-' + t[2] + '-' + t[3];
}
if (!date) {
  errors.push('Belegdatum fehlt oder unlesbar: "' + dateRaw +
           '" \u2014 Beleg-Datensatz pruefen');
}

// Unterschriften: ZWEI Parteien, unabhaengig beurteilt. Ein Kommissionsprotokoll
// ist erst unterzeichnet, wenn beide Felder einen handschriftlichen Zug tragen.
// "unclear" wird NICHT als vorhanden gefuehrt. Blockt bewusst nicht.
const SIG_STATES = ['present', 'missing', 'unclear'];
const sigState = v => SIG_STATES.indexOf(v) >= 0 ? v : 'unclear';
const word = { present: 'unterschrieben', missing: 'NICHT unterschrieben',
               unclear: 'nicht sicher erkennbar' };

const uKtt = sigState(d.signature_consignor);
const uKom = sigState(d.signature_commission_agent);
const bKtt = String(d.signature_consignor_finding == null ? '' : d.signature_consignor_finding).trim();
const bKom = String(d.signature_commission_agent_finding == null ? '' : d.signature_commission_agent_finding).trim();

if (uKtt !== 'present') {
  hints.push('Kommittent (selectedleafs) ' + word[uKtt] + (bKtt ? ' \u2014 gesehen: ' + bKtt : ''));
}
if (uKom !== 'present') {
  hints.push('Kommissionär ' + word[uKom] + (bKom ? ' \u2014 gesehen: ' + bKom : ''));
}

const kom = String(d.commission_agent == null ? '' : d.commission_agent).trim();

// Pruefername aus dem Kopfblock. Reine Dokumentation: fliesst in keine
// Geldformel und blockt nie.
const checkedBy = String(d.checked_by == null ? '' : d.checked_by).trim();

return {
  ok: errors.length === 0,
  date: date,
  customer_no: customer_no,
  commission_agent: kom,
  checked_by: checkedBy,
  signature_consignor: uKtt,
  signature_commission_agent: uKom,
  signed: (uKtt === 'present' && uKom === 'present'),
  noteText: hints.length ? hints.join(' \u00b7 ') : '',
  errorText: errors.join(' \u00b7 ')
};

// Store-Auflösung. Zwei Wege, klarer Vorrang, und erst hier entsteht der
// Dedup-Schluessel.
//
// 1. Gedruckte Kunden-Nr. gegen Stores.ID -- der Normalweg. Die Nummer ist
//    maschinenlesbar gedruckt und traegt zugleich den Bestands-Schluessel.
// 2. Faellt sie aus (nicht lesbar oder nicht in Stores gefuehrt), wird der
//    Kommissionär-Name gegen Stores.Name gesucht. Dieser Wert wurde bisher
//    nur als nicht-blockende Kreuzprobe verwendet; er ist gut genug als
//    Rueckfallebene, aber NUR bei genau einem Treffer. Mehrere Treffer sind
//    ein Nicht-Ergebnis, kein Ratespiel.
//
// Der Dedup-Schluessel BSP-{nummer}-{datum} entsteht aus der Store-NUMMER,
// nicht aus der gedruckten Kunden-Nr. Er muss zeichengleich mit der Formel im
// Feld Bestandspruefungen.ID sein ("BSP-" & Store-Nr & "-" & Datum) -- der
// Schluessel wird nicht mehr geschrieben, nur noch zum Suchen und fuer den
// Archiv-Dateinamen gebildet. Beide sind normalerweise identisch
// (Stores.ID traegt die JTL-Kundennummer); über die Nummer gebildet bleibt
// der Schluessel aber auch dann stabil, wenn der Store über den Namen kam.
const hints = [];

const txt = v => String(v == null ? '' : v).trim();
const arr = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; }
    catch (e) { return []; }
  }
  return [];
};

const customer_no = txt(input.customer_no);
const date    = txt(input.date);
const comm     = txt(input.commission_agent);

const numId     = txt(input.num_id);
const numName   = txt(input.num_name);
const numNumber = txt(input.num_number);

const nameMatches = arr(input.name_matches).filter(t => t && txt(t.id));

let storeId = '', storeName = '', storeNumber = '', source = '';

if (numId) {
  storeId = numId; storeName = numName; storeNumber = numNumber; source = 'kundennr';
} else if (nameMatches.length === 1) {
  const t = nameMatches[0];
  storeId = txt(t.id); storeName = txt(t.name); storeNumber = txt(t.number);
  source = 'name';
  hints.push('Store über den Namen "' + comm + '" aufgelöst (Kunden-Nr. ' +
            (customer_no ? customer_no + ' nicht in Stores gefunden' : 'auf dem Beleg nicht lesbar') + ')');
} else if (nameMatches.length > 1) {
  hints.push('Kommissionär "' + comm + '" trifft ' + nameMatches.length +
            ' Stores \u2014 nicht eindeutig, keine Auflösung');
}

// Kreuzprobe nur dann sinnvoll, wenn der Store über die Nummer kam -- kam er
// über den Namen, ist sie per Konstruktion erfuellt.
const lean = s => txt(s).toLowerCase()
  .replace(/[^a-z0-9\u00e4\u00f6\u00fc\u00df]+/g, ' ').trim();
if (source === 'kundennr' && comm && storeName &&
    lean(comm) !== lean(storeName)) {
  hints.push('Kommissionär auf dem Beleg (' + comm +
            ') weicht vom Store-Namen ab (' + storeName + ')');
}

const dedupkey = (storeNumber && date) ? 'BSP-' + storeNumber + '-' + date : '';

let error = '';
if (!storeId) {
  error = customer_no
    ? 'Kunden-Nr. ' + customer_no + ' nicht in Stores gefunden und Kommissionär "' +
      (comm || 'leer') + '" nicht eindeutig \u2014 Store anlegen oder Beleg prüfen'
    : 'Weder Kunden-Nr. noch Kommissionär-Name führen zu einem Store \u2014 Beleg prüfen';
}

return {
  ok: Boolean(storeId),
  store_id: storeId,
  store_name: storeName,
  store_number: storeNumber,
  source: source,
  dedupkey: dedupkey,
  dupText: dedupkey
    ? 'Duplikat von ' + dedupkey + ' \u2014 diesen Datensatz löschen'
    : 'Duplikat \u2014 diesen Datensatz löschen',
  errorText: error,
  noteText: hints.join(' \u00b7 ')
};

// Verdikt-Kaskade Kopf -> Store -> Dedup. Erstes Kriterium gewinnt.
//
// GEAENDERT ggue. v1: Die Store-Aufloesung samt Namens-Rueckfallebene und
// Kommissionaer-Kreuzprobe liegt jetzt in Modul 37; hier wird nur noch das
// Verdikt gefaellt.
const truthy = v => v === true || v === 'true';

// Bestehende Link-Werte des Datensatzes. Airtable liefert Link-Felder bei
// useColumnId als Array von Record-IDs; defensiv auch Objekte und Kommastrings.
const ids = v => {
  if (v === null || v === undefined || v === '') return [];
  let a = v;
  if (typeof a === 'string') {
    const t = a.trim();
    if (t.charAt(0) === '[') { try { a = JSON.parse(t); } catch (e) { a = t.split(','); } }
    else a = t.split(',');
  }
  if (!Array.isArray(a)) a = [a];
  return a.map(x => {
    if (x && typeof x === 'object') return String(x.id == null ? '' : x.id).trim();
    return String(x == null ? '' : x).trim();
  }).filter(x => /^rec[A-Za-z0-9]{14}$/.test(x));
};

const headerOk  = truthy(input.header_ok);
const storeId = String(input.store_id == null ? '' : input.store_id).trim();
const dupId   = String(input.dup_id == null ? '' : input.dup_id).trim();

const storeOld = ids(input.store_link_stock);
const salesOld = ids(input.salesperson_link_stock);

const extra = [];
if (input.noteText) extra.push(String(input.noteText));
if (input.store_note) extra.push(String(input.store_note));

// Pruefername: reine Dokumentation, nie blockend. Ein fehlender Name bleibt
// still; ein gedruckter Name OHNE Treffer in Vertriebler wird vermerkt.
const inspector = String(input.checked_by == null ? '' : input.checked_by).trim();
const salesId = String(input.salesperson_id == null ? '' : input.salesperson_id).trim();
if (inspector && !salesId) {
  extra.push('Pruefer "' + inspector + '" nicht in Vertriebler gefunden \u2014 nur dokumentiert');
}

// Link-Felder NIE mit einem leeren Array ueberschreiben. Kann der Lauf den Bezug
// nicht selbst aufloesen, wird der bestehende Stand zurueckgeschrieben -- der
// Write ist dann ein No-op statt einer stillen Loeschung.
const storeIds = storeId ? [storeId] : storeOld;
const salesIds = salesId ? [salesId] : salesOld;
if (!storeId && storeOld.length) {
  extra.push('Store nicht aus dem Beleg aufloesbar \u2014 bestehende Verknuepfung beibehalten');
}
if (!salesId && salesOld.length && inspector) {
  extra.push('Vertriebler nicht aufloesbar \u2014 bestehende Verknuepfung beibehalten');
}

let ok, hint;
if (!headerOk) {
  ok = false; hint = input.errorText || 'Kopf: unbekannter Fehler';
} else if (!storeId) {
  ok = false; hint = input.store_error || 'Store nicht aufloesbar';
} else if (dupId) {
  ok = false; hint = input.dupText || 'Duplikat';
} else {
  ok = true;  hint = extra.join(' \u00b7 ');
}

if (!ok && extra.length) hint = hint + ' \u00b7 ' + extra.join(' \u00b7 ');

return {
  ok: ok,
  salesperson_ids: salesIds,
  store_ids: storeIds,
  status: ok ? 'In Bearbeitung' : 'Ung\u00fcltig',
  hint: hint,
  noteText: ok ? extra.join(' \u00b7 ') : '',
  signed: truthy(input.signed)
};

// Positions-Vorentscheid. Modul 11 schreibt nur ab; hier wird sortiert:
// was ist eindeutig buchbar, was braucht eine zweite Lesung, was ist offen.
//
// WAS SICH GEGENUEBER v1 GEAENDERT HAT
// 1. Ein Zellwiderspruch toetet nicht mehr den ganzen Beleg. Frueher fiel bei
//    JEDEM Widerspruch zwischen Spalten-Vorlauf und Zuweisung der komplette
//    Beleg auf Ungueltig -- auch wenn acht von neun Zeilen sauber waren. Das
//    war ein Urteil über den EXTRAKTOR, nicht über den Beleg. Jetzt wird die
//    betroffene Zeile strittig gestellt und einzeln nachgelesen.
// 2. "unsicher" ist kein Verwerfungsgrund mehr, sondern der Anlass fuer die
//    zweite Lesung (Modul 38). Belegt am Beleg 11.05.2026: dort standen zwei
//    gut lesbare IST-Werte, die nur deshalb verlorengingen, weil die
//    Differenz-Spalte des alten Formulars gar nicht ausgefuellt war.
// 3. Sind IST UND Differenz beide unsicher, wird nicht mehr still rekonstruiert.
//    Eine unsichere Beobachtung durch eine unsichere Ableitung zu ersetzen
//    erzeugt eine Zahl ohne Deckung. Belegt am Beleg 14.07.2026 Pos 3.
//
// Hart bleiben nur zwei Bruchstellen, weil danach die ZUORDNUNG nicht mehr
// steht und jede Einzelzeile bedeutungslos waere:
//   - Zeilenzahl aus dem Vorlauf passt nicht zur Positionsliste
//   - Positionsnummern nicht lueckenlos ab 1
const errors = [];
const hints = [];
const notes = [];
const disputed = [];

const note = (kat, pos, no, text, fix) => {
  notes.push({ kat: kat, pos: pos, no: no || null,
                 fixtures: Boolean(fix), text: text });
  hints.push((pos ? 'Pos ' + pos + (no ? ' (' + no + ')' : '') + ': ' : '') + text);
};
const mirror_pos = [];

// Der Extrakt kommt als roher Antworttext (rawResponse) herein, nicht über
// einen Index ins content-Array: dessen Reihenfolge haengt davon ab, ob
// Extended Thinking aktiv ist.
let d = null;
let raw = input.extrakt;
if (raw && typeof raw === 'object') {
  d = raw;
} else {
  raw = String(raw == null ? '' : raw);
  const a = raw.indexOf('{');
  const b = raw.lastIndexOf('}');
  if (a >= 0 && b > a) raw = raw.slice(a, b + 1);
  if (!raw.trim()) {
    errors.push('Das Lesemodul hat nichts zurückgegeben \u2014 Beleg erneut einliefern, ' +
             'bei Wiederholung Scan verkleinern');
  } else {
    try { d = JSON.parse(raw); }
    catch (e) { errors.push('Antwort ist kein gültiges JSON: ' + e.message); }
  }
}

const together = () => [errors.join(' \u00b7 '), hints.join(' \u00b7 ')]
  .filter(function (t) { return t; }).join(' \u00b7 ');

const out = () => ({ ok: false, positions: [], disputed: [], batches: [],
  count: 0, total: 0, fixtures_total: 0,
  confirmed: 0, corrected: 0, contradiction: 0, assortment_missing: 0,
  notes: [],
  errorText: errors.join(' \u00b7 '),
  noteText: hints.join(' \u00b7 '),
  hint: together() });

if (!d || typeof d !== 'object') {
  if (!errors.length) errors.push('Leere Antwort');
  return out();
}

const all = Array.isArray(d.positions) ? d.positions : [];
if (all.length === 0) errors.push('keine Positionen extrahiert');

// WAECHTER 1 -- Zeilenzahl. Bleibt harter Blocker: stimmt sie nicht, laesst
// sich kein Vorlauf-Eintrag mehr sicher einer Zeile zuordnen.
const vl = (d.lead_columns && typeof d.lead_columns === 'object') ? d.lead_columns : null;
const isp = (vl && Array.isArray(vl.actual_column)) ? vl.actual_column : [];
const dsp = (vl && Array.isArray(vl.difference_column)) ? vl.difference_column : [];
const zg  = vl ? Number(vl.rows_total) : NaN;

if (!vl) {
  errors.push('spalten_vorlauf fehlt in der Antwort \u2014 Schema von Modul 11 prüfen');
} else {
  if (!isFinite(zg) || zg < 1) {
    errors.push('zeilen_gesamt nicht plausibel (' + vl.rows_total + ')');
  } else {
    if (isp.length !== zg) errors.push('IST-Spalte: ' + isp.length + ' Zellbefunde bei ' + zg + ' Zeilen');
    if (dsp.length !== zg) errors.push('Differenz-Spalte: ' + dsp.length + ' Zellbefunde bei ' + zg + ' Zeilen');
    if (all.length !== zg) errors.push('Positionsliste: ' + all.length + ' Zeilen, angekuendigt waren ' + zg);
  }
}
if (errors.length) return out();

// Artikelklassen. HANDELSWARE traegt die Abrechnung und bestimmt den Status;
// AUSSTATTUNG (POS-Displays) wird gebucht, zaehlt aber nicht in gesamt.
const FIXTURES = /^M\d/i;
const MERCHANDISE = /^\d{5}-\d{3}$/;

const zahl = v => (typeof v === 'number' && isFinite(v)) ? v : null;

// Differenz-Zeichenfolge -> delta (IST minus SOLL).
//   "4"  = 4 Stueck fehlen  -> -4      "+4" = 4 Stueck zuviel -> +4
//   "-"  = Strich           ->  0      "0"                    ->  0
// Alles andere ist nicht interpretierbar -> null.
const delta = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).replace(/\s+/g, '');
  if (s === '') return null;
  if (/[-\u2010\u2011\u2012\u2013\u2014\u2015]/.test(s) && /^[-\u2010\u2011\u2012\u2013\u2014\u2015*~.]+$/.test(s)) return 0;
  let m = s.match(/^\+(\d+)$/);
  if (m) return Number(m[1]);
  m = s.match(/^[-\u2010\u2011\u2012\u2013\u2014\u2015](\d+)$/);
  if (m) return -Number(m[1]);
  m = s.match(/^(\d+)$/);
  if (m) return -Number(m[1]);
  return null;
};

// Traegt die Differenz-Spalte anderswo auf dem Blatt Striche, ist eine als
// "leer" gemeldete Zelle verdaechtig: der Strich ist auf diesen Belegen der
// Normalfall fuer "keine Abweichung", und er wird nachweislich mal erkannt,
// mal nicht. Ein Beleg vom 16.06.2026 hat beides in derselben Spalte.
const DASH_FINDING = /(strich|haken|welle|zug|schraeg|quer)/i;
let dashAnywhere = false;
dsp.forEach(z => {
  if (z && !z.empty && DASH_FINDING.test(String(z.finding || ''))) dashAnywhere = true;
});

const positions = [];
let total = 0;
let fixtures_total = 0;
let confirmed = 0;
let corrected = 0;
let contradiction = 0;

const dispute = (pos, no, target, actualL, diffL, reason, fix) => {
  disputed.push({ pos: pos, no: no, target: target,
                  actual_reading: (actualL === null || actualL === undefined) ? null : actualL,
                  diff_reading: diffL === '' ? null : diffL,
                  fixtures: Boolean(fix), reason: reason });
};

all.forEach((p, i) => {
  const pos = Number(p.position);
  // WAECHTER 2 -- Lueckenlosigkeit. Harter Blocker, siehe Kopfkommentar.
  if (pos !== i + 1) {
    errors.push('Position ' + p.position + ' an Stelle ' + (i + 1) +
             ' \u2014 Zeile fehlt oder Reihenfolge gestört');
    return;
  }

  const vI = isp[i];
  const vD = dsp[i];

  const uns = Array.isArray(p.uncertain) ? p.uncertain : [];
  const u = f => uns.indexOf(f) >= 0;

  const no = String(p.article_number == null ? '' : p.article_number).trim();
  const label = String(p.description == null ? '' : p.description).trim();

  // Zeile ohne Artikelnummer ist kein Bestandsartikel (z. B. "Abholung vor Ort").
  if (!no) {
    note('info', pos, null, 'ohne Artikelnummer' + (label ? ' (' + label + ')' : ''));
    return;
  }

  const isFixture = FIXTURES.test(no);
  if (isFixture) {
    fixtures_total += 1;
  } else {
    if (!MERCHANDISE.test(no)) {
      note('info', pos, no, 'unbekanntes Artikelnummern-Muster, als Handelsware gewertet');
    }
    total += 1;
  }

  const target = zahl(p.target);
  const actual  = zahl(p.actual);
  const dTxt = (p.difference === null || p.difference === undefined) ? '' : String(p.difference);
  const dlt  = delta(p.difference);
  const dUns = u('differenz');
  const iUns = u('ist');

  // SOLL ist gedruckt. Ist es nicht sicher lesbar, taugt der Scan nicht als
  // Rekonstruktionsbasis -- eine zweite Lesung wuerde daran nichts aendern.
  if (target === null || u('soll')) {
    note('offen', pos, no, 'SOLL nicht sicher lesbar', isFixture);
    return;
  }

  // WAECHTER 3 -- Zellbefund gegen Wert. Frueher Beleg-Kill, jetzt strittig.
  if (!vI || !vD) {
    dispute(pos, no, target, actual, dTxt, 'Zellbefund fehlt im Spalten-Vorlauf', isFixture);
    return;
  }
  const actualEmpty = (actual === null);
  if (Boolean(vI.empty) !== actualEmpty) {
    dispute(pos, no, target, actual, dTxt,
      'IST beschrieben als "' + vI.finding + '" (leer=' + Boolean(vI.empty) +
      '), zugewiesen wurde ' + (actualEmpty ? 'null' : actual), isFixture);
    return;
  }
  const dLeer = (dTxt.trim() === '');
  if (Boolean(vD.empty) !== dLeer) {
    dispute(pos, no, target, actual, dTxt,
      'Differenz beschrieben als "' + vD.finding + '" (leer=' + Boolean(vD.empty) +
      '), zugewiesen wurde ' + (dLeer ? 'null' : '"' + dTxt + '"'), isFixture);
    return;
  }

  // Spiegel-Erkennung. Auf kurzen Zeilen -- typisch die POS-Displays mit SOLL 1
  // -- traegt die Differenz-Spalte haeufig nicht die Abweichung, sondern noch
  // einmal den gezaehlten Wert. Erkennbar daran, dass gedruckter SOLL,
  // handschriftlicher IST und vorzeichenloser Differenz-Betrag denselben Wert
  // tragen. Belegt am Beleg 13.07.2026 (Kunden-Nr. 10009).
  const dRein = dTxt.replace(/\s+/g, '');
  const mirror = dlt !== null && dlt !== 0 && actual !== null &&
                  target > 0 && target === actual &&
                  /^\d+$/.test(dRein) && Math.abs(dlt) === target;

  if (mirror) {
    positions.push({ pos: pos, no: no, target: target, actual: actual, fixtures: isFixture });
    if (iUns || dUns) confirmed += 1;
    mirror_pos.push(pos);
    return;
  }

  const diffSicher = (dlt !== null) && !dUns;

  // FALL 1 -- sicher gelesener IST. Drei Zweige, je nach Gegenprobe.
  //
  // Die Rechenabweichungs-Doktrin bleibt richtig: wer 19 zaehlt, 19 hinschreibt
  // und sich dann in der Differenzspalte verrechnet, hat einen Rechenfehler
  // gemacht, keinen Lesefehler -- dann gewinnt der IST (Beleg 16.06.2026, Pos 6:
  // IST 22, Diff "-6" fuer sechs Stueck UEBERbestand). Sie gehoert aber HINTER
  // die zweite Lesung, nicht davor. Denn "sicher" stammt hier aus EINER Ziehung,
  // und genau dessen Unzuverlaessigkeit begruendet die ganze Zweitlesung: auf dem
  // Alero-Beleg wurde zweimal 11 statt 10 gelesen, beide Male mit Selbstvertrauen.
  // Frueher wurde der Widerspruch hier vorab entschieden und nur protokolliert --
  // so ist auf S10027 Pos 3 IST 19 gebucht worden, waehrend SOLL 31 minus Diff 22
  // auf 9 führt. Diese Zeile erreichte den Konsens in Modul 39 nie.
  if (actual !== null && !iUns) {
    // 1a -- beide Routen einig. Staerkster Fall, still buchen.
    if (dlt !== null && (target + dlt) === actual) {
      confirmed += 1;
      positions.push({ pos: pos, no: no, target: target, actual: actual, fixtures: isFixture });
      return;
    }
    // 1b -- Widerspruch zwischen IST und Rechnung. Nicht mehr vorab entscheiden:
    // Modul 39 entscheidet mit doppelter Information. Traegt die Arithmetik den
    // IST auch nach der zweiten Lesung nicht, bleibt die Zeile offen.
    if (dlt !== null) {
      contradiction += 1;
      dispute(pos, no, target, actual, dTxt, 'IST ' + actual + ' sicher gelesen, Diff "' +
             dTxt + '" erg\u00e4be ' + (target + dlt), isFixture);
      return;
    }
    // 1c -- keine lesbare Differenz. Der IST ist die einzige Information; eine
    // rechnerische Deckung zu fordern waere unerfuellbar und wuerde jeden Beleg
    // mit unausgefuellter Differenzspalte in die Handpruefung schicken. Wird
    // also gebucht -- aber nicht mehr stillschweigend wie zuvor.
    note('pruefen', pos, no, 'IST ' + actual + ' gebucht ohne Gegenprobe (Diff ' +
         (dTxt.trim() === '' ? 'leer' : '"' + dTxt + '" nicht lesbar') + ')',
         isFixture);
    positions.push({ pos: pos, no: no, target: target, actual: actual, fixtures: isFixture });
    return;
  }

  // FALL 2 -- IST wirklich leer, Differenz sicher gelesen. Hier steht keine
  // konkurrierende Beobachtung im Weg, die Rekonstruktion ist die einzige
  // Quelle und darf still laufen (Beleg 01.06.2026: IST-Strich, Diff 18 -> 0).
  if (actual === null && diffSicher) {
    const rek = target + dlt;
    if (rek < 0) {
      dispute(pos, no, target, actual, dTxt,
        'SOLL ' + target + ' + Diff "' + dTxt + '" = ' + rek + ', negativ', isFixture);
      return;
    }
    positions.push({ pos: pos, no: no, target: target, actual: rek, fixtures: isFixture });
    note('korrigiert', pos, no, 'IST leer \u2192 ' + rek + ' (SOLL ' + target +
         ', Diff "' + dTxt + '")', isFixture);
    return;
  }

  // FALL 3 -- alles Uebrige geht in die zweite Lesung. Insbesondere JEDER
  // unsicher gelesene IST, auch wenn die Differenz sicher aussieht: eine
  // Beobachtung durch eine Ableitung zu ersetzen ist ein Eingriff, kein
  // Auslesen. Genau das ist am Beleg 14.07.2026 Pos 3 passiert -- IST "22?"
  // wurde still zu 17, und niemand konnte hinterher sagen, was auf dem Papier
  // stand.
  let reason;
  if (actual === null && dTxt.trim() === '') {
    reason = dashAnywhere
      ? 'IST und Diff beide als leer gemeldet, andere Zeilen tragen Striche'
      : 'IST und Diff beide leer';
  } else if (actual === null) {
    reason = 'IST leer, Diff "' + dTxt + '" nicht interpretierbar';
  } else if (dTxt.trim() === '') {
    reason = dashAnywhere
      ? 'IST ' + actual + ' unsicher, Diff als leer gemeldet (andere Zeilen tragen Striche)'
      : 'IST ' + actual + ' unsicher, keine Differenz zur Gegenprobe';
  } else {
    reason = 'IST ' + actual + ' unsicher, Diff "' + dTxt + '" erg\u00e4be ' +
            (dlt === null ? 'nichts Lesbares' : String(target + dlt));
  }
  dispute(pos, no, target, actual, dTxt, reason, isFixture);
});

// CHECK A -- Sortiments-Vollstaendigkeit. Kann NICHT unterscheiden, ob eine
// Zeile uebersehen wurde oder der Store die Sorte nicht mehr führt. Deshalb
// kein Blocker, sondern ein Hinweis mit NAMEN statt Zaehler.
const asList = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; }
    catch (e) { return []; }
  }
  return [];
};
// Bestaende.ID hat das Format "BST-{Store-Nr}-{SKU}". Die SKU traegt selbst
// einen Bindestrich (10004-002), deshalb wird NUR das Praefix und die
// Store-Nummer abgeschnitten -- nicht am ersten Bindestrich ueberhaupt.
const skuFromId = s => {
  const t = String(s == null ? '' : s);
  if (t.indexOf('BST-') !== 0) return '';
  const rest = t.slice(4);
  const i = rest.indexOf('-');
  return i < 0 ? '' : rest.slice(i + 1);
};

const onDocument = {};
all.forEach(p => {
  const n = String(p && p.article_number != null ? p.article_number : '').trim();
  if (n) onDocument[n] = true;
});

const fehlt = [];
asList(input.assortment).forEach(b => {
  const n = skuFromId(b && b.id);
  const target = Number(b && b.target);
  // SOLL <= 0 heisst buchhalterisch leer (ausgelistet/ausverkauft) -- eine
  // solche Zeile gehoert nicht auf den Beleg und darf keinen 'fehlt'-Hinweis
  // ausloesen. Fehlender/leerer SOLL (NaN) wird ebenso ausgeschlossen.
  if (n && !onDocument[n] && isFinite(target) && target > 0) fehlt.push(n);
});
if (fehlt.length) {
  note('pruefen', null, null, 'Best\u00e4nde f\u00fchrt ' + fehlt.join(', ') +
       ' \u2014 steht nicht auf dem Beleg');
}

if (mirror_pos.length) {
  note('info', null, null, 'Pos ' + mirror_pos.join(', ') +
       ': Diff wiederholt den Z\u00e4hlwert, als 0 gewertet');
}

if (errors.length) return out();

// Auftrag fuer die zweite Lesung. IMMER genau EIN Batch -- auch wenn nichts
// strittig ist. Zwei Gruende:
//   - Ein Batch statt einer je Zeile: das PDF laeuft hoechstens ein
//     zusaetzliches Mal zu Anthropic. Der Transfer ist der Engpass des
//     Szenarios (ein einzelner Lauf hat 61 MB bewegt), nicht die
//     Airtable-Operationen.
//   - Immer eins statt null: ein Feeder über ein LEERES Array laeuft null Mal,
//     und ob der nachgelagerte Aggregator dann trotzdem ein Bundle emittiert,
//     ist Make-Verhalten, auf das dieser Zweig sich nicht verlassen soll.
//     Waere es anders, bliebe jeder unstrittige Beleg auf "In Bearbeitung"
//     stehen. Der Feeder laeuft deshalb immer; ob der teure Anthropic-Call
//     stattfindet, entscheidet der Filter am Modul "Strittige Zellen
//     nachlesen" über anzahl > 0.
const batches = [{
  count: disputed.length,
  rows: disputed.map(s => s.pos).join(', '),
  order: disputed.map(s =>
    'Zeile ' + s.pos + ' (Artikel ' + s.no + ', gedruckter SOLL ' + s.target + ')'
  ).join('\n')
}];

return {
  ok: true,
  notes: notes,
  positions: positions,
  disputed: disputed,
  batches: batches,
  assortment_missing: fehlt.length,
  count: positions.length,
  total: total,
  fixtures_total: fixtures_total,
  confirmed: confirmed,
  corrected: corrected,
  contradiction: contradiction,
  errorText: '',
  noteText: hints.join(' \u00b7 '),
  hint: together()
};

// Abgleich der zweiten Lesung.
//
// Modul 12 hat die eindeutigen Zeilen bereits gebucht und die zweifelhaften in
// "strittig" gelegt. Modul 38 hat genau diese Zellen ein zweites Mal gelesen --
// ohne Kenntnis der ersten Lesung, damit die beiden Lesungen wirklich
// unabhaengig sind und nicht eine die andere bestaetigt, weil sie sie kennt.
//
// WARUM UEBERHAUPT ZWEIMAL LESEN
// Derselbe Zelltyp -- schmaler handschriftlicher IST, Strich in der Differenz --
// wurde auf einem Beleg richtig und auf einem anderen falsch gelesen. Das ist
// Streuung, kein Prompt-Defekt. Gegen Streuung hilft kein besserer
// Einzelversuch, sondern eine zweite Ziehung.
//
// ZWEI SIGNALKLASSEN -- DER KERN DIESES MODULS
// Ein IST-Wert kann auf zwei Wegen belegt werden:
//
//   H  Handschrift-Route: die IST-Zelle direkt lesen.
//   A  Arithmetik-Route:  gedrucktes SOLL + gelesene Differenzzelle.
//
// Zwei Blicke auf DIESELBE IST-Zelle sind kein doppelter Beleg. Sieht eine 0
// aus wie eine 9, lesen beide Blicke denselben Fehler -- die Uebereinstimmung
// wiederholt ihn, statt ihn zu pruefen. Belegt auf S10027 Pos 3: zweimal "19"
// gelesen, waehrend gedrucktes SOLL 31 minus Differenz 22 auf 9 führt.
// Gebucht wurde 19 -- eine Falschbuchung mit zwei uebereinstimmenden Lesungen
// als Deckung. Die A-Route kann so einen Fehler aufdecken, weil sie eine andere
// Zelle liest und eine gedruckte Zahl mitbringt.
//
// DECKUNGS-GATE (die eigentliche Regel)
// Gebucht wird nur ein Wert, auf den mindestens EIN A-Signal zeigt. Punkte
// allein genuegen nicht -- eine reine Handschrift-Mehrheit bleibt offen, egal
// wie hoch sie summiert. Das ist bewusst strenger als eine Gewichtung: Gewichte
// koennen sich zufaellig über eine Schwelle addieren, ein Gate kann das nicht.
// Frueher stand hier nur eine Punkteschwelle, und genau daran ist Pos 3
// durchgerutscht: der staerkste Wert hatte keinen Konkurrenten, damit entfiel
// die Vorsprungspruefung und die Schwelle allein trug die Buchung.
//
// GEWICHTE (entscheiden nur noch zwischen Werten, die BEIDE Deckung haben)
//   H  erste Lesung IST                        0.5
//   H  zweite Lesung IST     sicher 1.0 / unsicher 0.5
//   A  erste Lesung SOLL+Differenz             1.0
//   A  zweite Lesung SOLL+Differenz  sicher 2.0 / unsicher 1.0
//
// Gebucht wird bei mindestens 2.0 Punkten UND mindestens 1.0 Vorsprung UND
// Deckung. Widersprechen sich Handschrift und Arithmetik, reisst die
// Vorsprungsregel -- die Zeile bleibt offen. Das ist gewollt: ein
// widerspruechlicher Beleg gehoert vor menschliche Augen, nicht in die Buchung.
//
// SOLL ist hier immer vorhanden: Waechter 2 in Modul 12 stellt eine Zeile mit
// unsicherem SOLL nie strittig, sondern legt sie direkt offen ab. Die A-Route
// steht also grundsaetzlich zur Verfuegung, sobald eine Differenz gelesen wird.
const arr = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; }
    catch (e) { return []; }
  }
  return [];
};

const positions = arr(input.positions).slice();
const disputed   = arr(input.disputed);
const notes    = arr(input.notes).slice();

const zahl = v => (typeof v === 'number' && isFinite(v)) ? v
  : (typeof v === 'string' && v.trim() !== '' && isFinite(Number(v)) ? Number(v) : null);

const delta = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).replace(/\s+/g, '');
  if (s === '') return null;
  if (/[-\u2010\u2011\u2012\u2013\u2014\u2015]/.test(s) && /^[-\u2010\u2011\u2012\u2013\u2014\u2015*~.]+$/.test(s)) return 0;
  let m = s.match(/^\+(\d+)$/);
  if (m) return Number(m[1]);
  m = s.match(/^[-\u2010\u2011\u2012\u2013\u2014\u2015](\d+)$/);
  if (m) return -Number(m[1]);
  m = s.match(/^(\d+)$/);
  if (m) return -Number(m[1]);
  return null;
};

const note = (kat, pos, no, text, fix) => {
  notes.push({ kat: kat, pos: pos, no: no || null,
                 fixtures: Boolean(fix), text: text });
};

// Zweite Lesung einsammeln. Der Aggregator liefert null oder ein Bundle; kam
// nichts (kein Streitfall, oder das Modul lief auf Fehler und wurde ignoriert),
// bleibt die Karte leer und alle strittigen Zeilen bleiben offen.
//
// Neben der Antwort tragen die Bundles zwei Diagnosewerte aus Modul 38:
// "grund" ist finishReason, "thoughts" ist thoughtsTokenCount. Bricht Gemini am
// Output-Budget ab, liefert es abgeschnittenes JSON -- der Parser unten faengt
// das still ab, und ohne diese beiden Werte war anschliessend nicht
// unterscheidbar, ob das Modul nichts zu sagen hatte oder mitten im Satz
// abgeschnitten wurde. finishReason haengt nicht am parts-Pfad und kommt
// deshalb auch dann durch, wenn die Antwort selbst leer ankommt.
const map = {};
let secondThere = false;
let abortReason = '';
let thinkTokens = null;

arr(input.second).forEach(b => {
  if (!b) return;

  const g = (b.reason === null || b.reason === undefined) ? '' : String(b.reason).trim();
  if (g && g.toUpperCase() !== 'STOP' && abortReason.indexOf(g) < 0) {
    abortReason = abortReason ? abortReason + ', ' + g : g;
  }
  const th = zahl(b.thoughts);
  if (th !== null) thinkTokens = (thinkTokens === null ? 0 : thinkTokens) + th;

  let raw = b.answer;
  if (raw === null || raw === undefined) return;
  if (typeof raw === 'object') {
    // schon geparst
  } else {
    raw = String(raw);
    const a = raw.indexOf('{');
    const z = raw.lastIndexOf('}');
    if (a >= 0 && z > a) raw = raw.slice(a, z + 1);
    if (!raw.trim()) return;
    try { raw = JSON.parse(raw); } catch (e) { return; }
  }
  const cells = (raw && Array.isArray(raw.cells)) ? raw.cells : [];
  cells.forEach(z => {
    const no = zahl(z && z.row);
    if (no === null) return;
    map[no] = z;
    secondThere = true;
  });
});

let confirmed_second = 0;
let decided = 0;
let open_second = 0;
let without_second_reading = 0;
let without_coverage = 0;
let contradiction_actual = 0;

disputed.forEach(s => {
  const pos  = Number(s.pos);
  const no   = String(s.no == null ? '' : s.no);
  const target = zahl(s.target);
  const fix = Boolean(s.fixtures);
  const reason = String(s.reason == null ? '' : s.reason);

  const points = {};
  const give = (wert, p, source, arithmetic) => {
    if (wert === null || wert === undefined || !isFinite(wert) || wert < 0) return;
    const k = String(wert);
    if (!points[k]) points[k] = { wert: wert, p: 0, sources: [], coverage: false };
    points[k].p += p;
    points[k].sources.push(source);
    if (arithmetic) points[k].coverage = true;
  };

  // Signale aus der ersten Lesung.
  const actual1 = zahl(s.actual_reading);
  const d1   = delta(s.diff_reading);
  give(actual1, 0.5, 'Lesung 1 IST', false);
  if (target !== null && d1 !== null) give(target + d1, 1.0, 'Lesung 1 Rechnung', true);

  // Signale aus der zweiten Lesung.
  const z = map[pos];
  let actual2 = null, d2 = null, certain2 = false;
  if (z) {
    actual2 = zahl(z.actual);
    d2 = delta(z.difference);
    certain2 = (z.certain === true || z.certain === 'true');
    give(actual2, certain2 ? 1.0 : 0.5, 'Lesung 2 IST', false);
    if (target !== null && d2 !== null) {
      give(target + d2, certain2 ? 2.0 : 1.0, 'Lesung 2 Rechnung', true);
    }
  }

  const rank = Object.keys(points).map(k => points[k]).sort((a, b) => b.p - a.p);
  const best = rank[0] || null;
  const second2 = rank[1] || null;

  const covered    = Boolean(best && best.coverage);
  const enoughP     = Boolean(best && best.p >= 2.0);
  const lead  = Boolean(best && (!second2 || (best.p - second2.p) >= 1.0));

  // Gegenrichtung absichern. Das Deckungs-Gate allein liesse die Arithmetik den
  // sicher gelesenen IST UEBERSTIMMEN: auf S10027 Pos 3 (SOLL 31, IST 19, Diff
  // "22") summieren die beiden Rechen-Signale auf 3.0 gegen 1.5 fuer die
  // Handschrift -- gebucht wuerde 9. Hat der Ausfuellende nur im Kopf falsch
  // gerechnet, ist 19 richtig und 9 waere eine neue Falschbuchung, nur mit
  // umgekehrtem Vorzeichen. Liest die fokussierte zweite Lesung den IST sicher
  // und weicht sie vom Rechenergebnis ab, ist der Beleg in sich widersprüchlich
  // -- dann entscheidet keine Seite, sondern ein Mensch.
  const istWiderspruch = Boolean(z && certain2 && actual2 !== null && best && actual2 !== best.wert);

  const viable = covered && enoughP && lead && !istWiderspruch;

  if (viable) {
    positions.push({ pos: pos, no: no, target: target, actual: best.wert, fixtures: fix });
    decided += 1;
    const document = best.sources.join(' + ');
    if (actual1 !== null && actual1 === best.wert) {
      confirmed_second += 1;
      note('korrigiert', pos, no, 'IST ' + best.wert +
           ' rechnerisch gedeckt (' + document + ')', fix);
    } else {
      note('korrigiert', pos, no, 'IST ' +
           (actual1 === null ? 'leer' : actual1 + '?') + ' \u2192 ' + best.wert +
           ' (' + document + ')', fix);
    }
    return;
  }

  open_second += 1;
  if (!z) {
    without_second_reading += 1;
    note('offen', pos, no, reason + ' \u2014 keine zweite Lesung erhalten' +
         (abortReason ? ' (' + abortReason + ')' : ''), fix);
  } else if (!best) {
    note('offen', pos, no, reason + ' \u2014 auch die zweite Lesung liefert keinen Wert', fix);
  } else if (!covered) {
    // Der wichtigste neue Fall: der Wert liegt vor, aber nur die Handschrift
    // traegt ihn. Genau hier waere frueher falsch gebucht worden.
    without_coverage += 1;
    note('offen', pos, no, reason + ' \u2014 IST ' + best.wert +
         ' nur handschriftlich gelesen (' + best.sources.join(', ') +
         '), keine Deckung durch SOLL ' + target + ' plus Differenz', fix);
  } else if (istWiderspruch) {
    contradiction_actual += 1;
    // Eigenstaendige, vollstaendige Formulierung -- der grund aus Modul 12 sagte
    // dasselbe und stuende sonst doppelt (S10027 Pos 3).
    note('offen', pos, no, 'gez\u00e4hlter IST ' + actual2 +
         ' widerspricht der Differenz-Angabe "' +
         (s.diff_reading == null ? '' : s.diff_reading) + '" (erg\u00e4be ' + best.wert +
         ') \u2014 Beleg in sich widerspr\u00fcchlich, bitte pr\u00fcfen', fix);
  } else {
    const fields = rank.slice(0, 2).map(r => r.wert + ' (' + r.sources.join(', ') +
      (r.coverage ? ', gerechnet' : ', nur Handschrift') + ')');
    note('offen', pos, no,
      reason + ' \u2014 zweite Lesung bringt keine Klarheit: ' + fields.join(' gegen '), fix);
  }
});

positions.sort((a, b) => Number(a.pos) - Number(b.pos));

const n = v => { const x = Number(v); return isFinite(x) ? x : 0; };

// Flachfassung der hier neu entstandenen Notizen. Modul 21 baut den lesbaren
// Hinweis aus der kategorisierten Liste; die Flachfassung braucht nur der
// Ungueltig-Pfad (Modul 29), der Modul 21 nie erreicht.
const neuFlach = notes.slice(arr(input.notes).length).map(x =>
  (x.pos ? 'Pos ' + x.pos + (x.no ? ' (' + x.no + ')' : '') + ': ' : '') + x.text
).join(' \u00b7 ');

// Laufdiagnose. Steht bewusst im Hinweis und nicht nur im Log: nach einem Lauf
// soll ohne API-Abfrage ablesbar sein, WARUM Zeilen offen blieben -- Abbruch am
// Output-Budget, fehlende Deckung oder gegriffene Bruecke sind drei sehr
// verschiedene Befunde mit drei verschiedenen Konsequenzen.
// Nur handlungsrelevante Laufdiagnose in den Hinweis. Die Zaehler ohne_deckung
// und widerspruch_ist stehen bereits namentlich als offene Zeilen -- als Zaehler
// wiederholt waeren sie doppelt. Ein Gemini-Abbruch am Output-Budget dagegen
// erklaert technisch verursachte offene Zeilen und bleibt sichtbar; die
// Denk-Tokens bleiben als Rueckgabefeld fuers Log, nicht im Hinweis.
const diagnostic = [];
if (abortReason) diagnostic.push('Zweitlesung am Budget abgebrochen (' + abortReason + ')');
const diagText = diagnostic.join(' \u00b7 ');

// Die Diagnose muss als eigene notizen-Zeile raus, nicht nur über notiz/hinweis:
// Modul 21 baut den sichtbaren Hinweis auf dem Erfolgspfad AUS "notizen" und
// liest notiz/hinweis nicht -- die braucht nur der Ungueltig-Pfad (Modul 29).
// Beim ersten Lauf mit dieser Diagnose blieb sie deshalb komplett unsichtbar.
// Steht bewusst NACH der neuFlach-Berechnung, sonst stuende der Text dort doppelt.
if (diagText) note('diagnose', null, null, diagText, false);

const join = (a, b) => [String(a == null ? '' : a), b]
  .filter(function (t) { return t; }).join(' \u00b7 ');

return {
  ok: true,
  positions: positions,
  count: positions.length,
  notes: notes,
  total: n(input.total),
  fixtures_total: n(input.fixtures_total),
  confirmed: n(input.confirmed) + confirmed_second,
  disputed_total: disputed.length,
  second_reading_ran: secondThere,
  second_reading_abort: abortReason,
  think_tokens: thinkTokens,
  decided: decided,
  open: open_second,
  without_second_reading: without_second_reading,
  without_coverage: without_coverage,
  contradiction_actual: contradiction_actual,
  errorText: '',
  noteText: join(join(input.noteText, neuFlach), diagText),
  hint: join(join(input.hint, neuFlach), diagText)
};

// Waechter + Statusverdikt + Hinweis-Aufbau + Kontrollflag.
//
// STATUS zaehlt ausschliesslich Buchungen von HANDELSWARE -- er sagt, ob die
// Abrechnungsbasis vollstaendig ist. Ausstattung (POS-Displays) wird gebucht und
// über Bestaende.Differenz fakturiert, dominiert aber nicht die Anzeige.
//
// INVENTAR GEPRUEFT ist die zweite, strengere Aussage: gesetzt nur, wenn JEDE
// Zeile mit Artikelnummer auf dem Beleg eingetragen, verifiziert und gebucht
// wurde -- Handelsware UND Ausstattung. Teilweise oder gar nicht bedeutet leer.
// Damit traegt der Status die Abrechnung und das Flag den Bestand; sie duerfen
// bewusst auseinanderlaufen (ein Beleg mit vollstaendiger Handelsware und einem
// leeren Display-Feld ist "Abgeschlossen", aber NICHT geprueft).
//
// Der Hinweis ist nach DRINGLICHKEIT sortiert und in Sektionen gegliedert.
// Grundregel: jede Information steht GENAU EINMAL drin.
//
// Der SOLL-Vergleich gegen Bestaende ist per Definition KEIN Buchungskriterium:
// Bestaende.SOLL ist ein Momentanwert (Geliefert minus Verkauft, Stand heute),
// der gedruckte SOLL ist historisch -- bei nachtraeglich importierten Belegen
// weichen beide zwangslaeufig ab.
const arr = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; }
    catch (e) { return []; }
  }
  return [];
};
const zahl = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return isFinite(n) ? n : null;
};
const truthy = v => v === true || v === 'true';

const FIXTURES = /^M\d/i;
const actualM = v => FIXTURES.test(String(v || ''));

const rows = arr(input.rows);
const released = arr(input.released);
const notes = arr(input.notes);

const booked = rows.filter(z => z && !actualM(z.no)).length;
const booked_all = rows.length;
const g = zahl(input.total);
const total = g === null ? booked : g;
const aG = zahl(input.fixtures_total);
const fixtures_total = aG === null ? 0 : aG;
const best = zahl(input.confirmed) || 0;

// Beleg-SOLL gegen gefuehrten Bestand -- nur zaehlen, nicht ausschreiben.
let abw = 0;
rows.forEach(z => {
  if (!z) return;
  const document = zahl(z.target);
  const listed = zahl(z.stock_target);
  if (document === null || listed === null) return;
  if (document !== listed) abw += 1;
});

// Von Modul 39 freigegeben, aber Produkt oder Bestandszeile nicht aufloesbar.
const mapped = {};
rows.forEach(z => { if (z) mapped[Number(z.pos)] = true; });

const show = n => (n.pos ? 'Pos ' + n.pos + (n.no ? ' (' + n.no + ')' : '') + ': ' : '') + n.text;
const kat = k => notes.filter(n => n && n.kat === k);

const openTrade = [];
const openFix = [];
kat('offen').forEach(n => (n.fixtures ? openFix : openTrade).push(n));
released.forEach(p => {
  if (!p || mapped[Number(p.pos)]) return;
  const n = { pos: p.pos, no: p.no, text: 'Produkt oder Bestandszeile nicht gefunden' };
  (actualM(p.no) ? openFix : openTrade).push(n);
});

let status;
if (total === 0) {
  // Reiner Ausstattungsbeleg: nichts abzurechnen, also nichts unvollstaendig.
  status = booked_all > 0 ? 'Abgeschlossen' : 'Ung\u00fcltig';
} else if (booked === 0)  status = 'Ung\u00fcltig';
else if (booked < total) status = 'Teilgebucht';
else                       status = 'Abgeschlossen';

// Kontrollflag: alle Artikelzeilen des Belegs sind gebucht, keine offen.
// INVENTAR = die Ausstattung beim Store (POS-Displays, M-Artikelnummern) --
// NICHT die Handelsware. 'Inventar geprueft' ist ein eigenstaendiges Flag ueber
// genau dieses Inventar, unabhaengig vom Buchungsstatus der Handelsware (analog
// zu 'unterzeichnet'). Gesetzt, sobald jede Ausstattungs-Position geprueft und
// gebucht ist -- also keine offene Ausstattung mehr. Eine offene Handelsware-Zeile
// (z. B. ein widerspruechlicher Kratom-IST) beruehrt das Inventar-Flag nicht.
const inventory_checked =
  fixtures_total > 0 &&
  openFix.length === 0;

const block = [];
const section = (title, list) => {
  if (list.length) block.push(title + '\n' + list.join('\n'));
};

// Zahl zeigt die OFFENEN, konsistent mit der Liste darunter -- nicht den
// gebuchten Anteil (das las sich als '5 von 6 nicht gebucht', genau falsch).
section('\u26a0 NICHT GEBUCHT (' + openTrade.length + ' von ' + total + ' Handelsware)',
  openTrade.map(show));
section('\u26a0 AUSSTATTUNG', openFix.map(show));
section('\u26a0 PR\u00dcFEN', kat('pruefen').map(show));
section('KORRIGIERT', kat('korrigiert').map(show));

const documentRows = [];
if (input.header_note) documentRows.push(String(input.header_note));
kat('info').forEach(n => documentRows.push(show(n)));
section('BELEG', documentRows);

// Fallback: kommt keine kategorisierte Notiz an, lieber die Flachfassung zeigen
// als gar nichts.
if (!notes.length && input.pos_note) block.push(String(input.pos_note));

const foot = [];
if (abw > 0) {
  foot.push('SOLL vs. Best\u00e4nde: ' + abw +
            ' Zeile(n) abweichend (historisch, kein Buchungskriterium)');
}
if (best > 0) foot.push(best + ' Zeile(n) durch Kreuzprobe best\u00e4tigt');
if (truthy(input.secondReading)) {
  foot.push('Zweifelhafte Zellen wurden ein zweites Mal gelesen');
}
if (inventory_checked) foot.push('Inventar vollst\u00e4ndig gepr\u00fcft');
kat('diagnose').forEach(n => foot.push(n.text));
if (foot.length) block.push(foot.join('\n'));

return {
  hint: block.join('\n\n'),
  status: status,
  inventory_checked: inventory_checked,
  booked: booked,
  booked_all: booked_all,
  total: total,
  fixtures_total: fixtures_total,
  fixtures_open: openFix.length,
  confirmed: best,
  deviations: abw
};

// Endpunkt "nichts aufloesbar": keine einzige freigegebene Zeile hat Produkt
// UND Bestandszeile gefunden. Eine gezaehlte Sorte ohne Lieferhistorie darf
// nicht stillschweigend angelegt werden.
const arr = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; }
    catch (e) { return []; }
  }
  return [];
};

const all = arr(input.all);
const mapped = {};
arr(input.resolved).forEach(r => { if (r) mapped[Number(r.pos)] = true; });
const missing = all.filter(p => p && !mapped[Number(p.pos)]);

const parts = [];
if (input.header_note) parts.push(String(input.header_note));
if (input.pos_note)  parts.push(String(input.pos_note));
parts.push('Produkt oder Bestandszeile nicht gefunden: ' +
  (missing.length ? missing.map(p => 'Pos ' + p.pos + ' (' + p.no + ')').join(', ')
                  : 'unbekannt'));

return {
  missing: missing.map(p => p.pos),
  count: missing.length,
  hint: parts.join(' \u00b7 ')
};
